/// A point on the local grid: metres east, metres north, elevation in metres.
#[derive(Debug, Clone, PartialEq)]
pub struct Point {
    pub x: f64,
    pub y: f64,
    pub elev: f64,
}

/// Horizontal distance in metres.
pub fn dist(a: &Point, b: &Point) -> f64 {
    ((b.x - a.x).powi(2) + (b.y - a.y).powi(2)).sqrt()
}

