// ---- parse -------------------------------------------------------------------------------------------

#[test]
fn decimals_and_negative_elevations_are_kept() {
    let pts = parse_waypoints("A; 0; 0; 1203.5\n-; 3; 4; -12.25\nB; 6; 8; 0\n").unwrap();
    assert_eq!(pts[0].point.elev, 1203.5);
